-- Passage rg4-main-idea-summary-p08
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('e9beb338-f6aa-5007-97cc-69f7dc4feb34', 'rg4-main-idea-summary-p08', (select id from public.skills where slug = 'read-g4-main-idea-summary'), null,
        '3-5', $q$Why Our School Needs a Walking Club$q$, $q$Our school should start a walking club that meets before classes begin. A walking club would help students be healthier, happier, and ready to learn.

First, walking is good exercise. Doctors say children need to move their bodies every day. Many students ride to school in a bus or a car and then sit for hours. A short walk around the field each morning would give everyone a healthy start.

Second, walking helps students feel calm and focused. After moving outside in fresh air, many people find it easier to pay attention. Our teachers have noticed that students are often restless in the first class of the day. A walk could help with that.

Third, a walking club would help students make friends. Walking side by side is a great time to talk. Students from different grades could meet each other and share ideas.

Some people may worry that a club would cost too much money. However, walking needs no special equipment. All we need is the school field, a few parent helpers, and comfortable shoes.

For all these reasons, our school should start a walking club. Let's take the first step together!$q$, 'draft')
